/**
 * Two titles the site states more precisely than the workbook does.
 *
 * The workbook calls both coordinating managers "Program Manager". The
 * department's own portrait files name the jobs — Business projects
 * management manager, Technology projects management manager — and those
 * are the titles the site has been showing. Replacing a specific real
 * title with a generic one is a loss of content rather than an update, so
 * the specific form is kept and the difference is reported rather than
 * resolved silently.
 */
const ROLE_OVERRIDES: Record<string, string> = {
  'PM-002': 'Business Projects Management Manager',
  'PM-003': 'Technology Projects Management Manager',
}

/**
 * A title that has not been confirmed yet. Held as a constant because two
 * places have to agree about it: the record, and every surface that has to
 * decide whether there is a role to print.
 */
export const ROLE_UNCONFIRMED = 'Role to be confirmed'

/**
 * The role as it should be displayed, or nothing.
 *
 * "Role to be confirmed" is a note about the data, not a job. Printed
 * under a portrait or inside a profile it tells the reader nothing about
 * the person and reads as filler, so the line is left out instead — the
 * layouts all treat the role as optional.
 */
export function displayRole(p: Person): string | undefined {
  return !p.role || p.role === ROLE_UNCONFIRMED ? undefined : p.role
}

/** Team Leader, coordinating manager, or colleague. */
function levelOf(isLeadership: boolean, leadershipOrder?: number): PersonLevel {
  if (!isLeadership) return 'team-member'
  return leadershipOrder === 1 ? 'team-lead' : 'program-manager'
}

export const PEOPLE: Person[] = WB_PEOPLE.flatMap((w) => {
  const asset = ASSETS[w.id]
  const team = TEAM_KEYS[w.team ?? '']
  /* A workbook record with no portrait table entry, or on a team this
     site does not compose, is not silently half-rendered. It is left out
     and reported by `validatePeopleData` below. */
  if (!asset || !team) return []
  return [
    {
      id: asset.id,
      name: w.name ?? asset.id,
      role: ROLE_OVERRIDES[w.id] ?? w.role ?? ROLE_UNCONFIRMED,
      team,
      photo: `${PORTRAITS}${asset.photo}`,
      photoAlt: w.photoAlt ?? `Portrait of ${w.name ?? ''}`.trim(),
      /* The workbook says "center" for every portrait, which is the value
         it was pre-filled with rather than a decision about these images.
         These sources are small upright shots with the face high in
         frame, and the house focal point is set for exactly that — see
         portraitFraming. */
      photoPosition: PORTRAIT_FOCUS,
      shortBio: w.shortBio,
      shortBioEmphasis: w.shortBioEmphasis,
      keyContribution: w.keyContribution,
      keyContributionEmphasis: w.keyContributionEmphasis,
      personalFact: w.personalFact,
      personalFactEmphasis: w.personalFactEmphasis,
      accent: TEAM_ACCENTS[team],
      isLeadership: w.isLeadership,
      leadershipLevel: levelOf(w.isLeadership, w.leadershipOrder),
      leadershipOrder: w.leadershipOrder,
      displayOrder: w.displayOrder,
    },
  ]
})

/** Team roster, leadership first, then exact display order. */
export function peopleByTeam(team: string): Person[] {
  return PEOPLE.filter((p) => p.team === team).sort((a, b) => {
    if (a.isLeadership !== b.isLeadership) return a.isLeadership ? -1 : 1
    if (a.isLeadership && b.isLeadership) {
      return (a.leadershipOrder ?? 99) - (b.leadershipOrder ?? 99)
    }
    return a.displayOrder - b.displayOrder
  })
}

export function teamCount(team: string): number {
  return PEOPLE.filter((p) => p.team === team).length
}

/**
 * Development-time sanity check: warns (never throws) when the roster
 * disagrees with the structure above. Safe in production.
 */
export function validatePeopleData(): void {
  const ids = new Set<string>()
  for (const p of PEOPLE) {
    if (ids.has(p.id)) console.warn(`[peopleData] Duplicate person id: ${p.id}`)
    ids.add(p.id)
  }
  if (PEOPLE.length !== WB_PEOPLE.length) {
    console.warn(
      `[peopleData] ${WB_PEOPLE.length} people in the workbook, ${PEOPLE.length} placed. ` +
        'A record with no portrait-table entry is not rendered.',
    )
  }
  if (PEOPLE.length !== TOTAL_EXPECTED) {
    console.warn(`[peopleData] Total roster is ${PEOPLE.length}, expected ${TOTAL_EXPECTED}.`)
  }
  for (const [team, expected] of Object.entries(TEAM_SIZE_EXPECTED)) {
    const actual = teamCount(team)
    if (actual !== expected) {
      console.warn(`[peopleData] ${team}: ${actual} people, expected ${expected}.`)
    }
  }
  for (const [team, expected] of Object.entries(TEAM_LEADERSHIP_EXPECTED)) {
    const actual = PEOPLE.filter((p) => p.team === team && p.isLeadership).length
    if (actual !== expected) {
      console.warn(
        `[peopleData] ${team}: ${actual} leadership function(s), expected ${expected}.`,
      )
    }
  }
}
